&#34;, adc_value[7]); } } void rcu_config(void) { /* enable GPIOA clock */ rcu_periph_clock_enable(RCU_GPIOA); /* enable ADC0 clock */ rcu_periph_clock_enable(RCU_ADC0); /* enable DMA0 clock */ rcu_periph_clock_enable(RCU_DMA0); /* config ADC clock */ rcu_adc_clock_config(RCU_CKADC_CKAPB2_DIV4); } void gpio_config(void) { /* config the GPIO as analog mode */ gpio_init(GPIOA, GPIO_MODE_AIN, GPIO_OSPEED_MAX, GPIO_PIN_0|GPIO_PIN_1|GPIO_PIN_2|GPIO_PIN_3); gpio_init(GPIOA, GPIO_MODE_AIN, GPIO_OSPEED_MAX, GPIO_PIN_4|GPIO_PIN_5|GPIO_PIN_6|GPIO_PIN_7); /* config the GPIO as floating input mode, for EXTI */ gpio_init(GPIOA, GPIO_MODE_IN_FLOATING, GPIO_OSPEED_MAX,GPIO_PIN_11); } void dma_config(void) { /* ADC_DMA_channel configuration */ dma_parameter_struct dma_data_parameter; /* ADC DMA_channel configuration */ dma_deinit(DMA0, DMA_CH0); /* initialize DMA single data mode */ dma_data_parameter.periph_addr = (uint32_t)(&amp;ADC_RDATA(ADC0)); dma_data_parameter.periph_inc = DMA_PERIPH_INCREASE_DISABLE; dma_data_parameter.memory_addr = (uint32_t)(&amp;adc_value); dma_data_parameter.memory_inc = DMA_MEMORY_INCREASE_ENABLE; dma_data_parameter.periph_width = DMA_PERIPHERAL_WIDTH_16BIT; dma_data_parameter.memory_width = DMA_MEMORY_WIDTH_16BIT; dma_data_parameter.direction = DMA_PERIPHERAL_TO_MEMORY; dma_data_parameter.number = 8; dma_data_parameter.priority = DMA_PRIORITY_HIGH; dma_init(DMA0, DMA_CH0, &amp;dma_data_parameter); dma_circulation_enable(DMA0, DMA_CH0); /* enable DMA channel */ dma_channel_enable(DMA0, DMA_CH0); } void adc_config(void) { /* ADC continuous function disable */ adc_special_function_config(ADC0, ADC_CONTINUOUS_MODE, DISABLE); adc_special_function_config(ADC0, ADC_SCAN_MODE, DISABLE); /* ADC trigger config */ adc_external_trigger_source_config(ADC0, ADC_ROUTINE_CHANNEL, ADC0_1_EXTTRIG_ROUTINE_EXTI_11); /* ADC data alignment config */ adc_data_alignment_config(ADC0, ADC_DATAALIGN_RIGHT); /* ADC mode config */ adc_mode_config(ADC_MODE_FREE); /* ADC channel length config */ adc_channel_length_config(ADC0, ADC_ROUTINE_CHANNEL, 8); /* ADC DMA function enable */ adc_dma_mode_enable(ADC0); /* ADC routine channel config */ adc_routine_channel_config(ADC0, 0, ADC_CHANNEL_0, ADC_SAMPLETIME_55POINT5); adc_routine_channel_config(ADC0, 1, ADC_CHANNEL_1, ADC_SAMPLETIME_55POINT5); adc_routine_channel_config(ADC0, 2, ADC_CHANNEL_2, ADC_SAMPLETIME_55POINT5); adc_routine_channel_config(ADC0, 3, ADC_CHANNEL_3, ADC_SAMPLETIME_55POINT5); adc_routine_channel_config(ADC0, 4, ADC_CHANNEL_4, ADC_SAMPLETIME_55POINT5); adc_routine_channel_config(ADC0, 5, ADC_CHANNEL_5, ADC_SAMPLETIME_55POINT5); adc_routine_channel_config(ADC0, 6, ADC_CHANNEL_6, ADC_SAMPLETIME_55POINT5); adc_routine_channel_config(ADC0, 7, ADC_CHANNEL_7, ADC_SAMPLETIME_55POINT5); adc_external_trigger_config(ADC0, ADC_ROUTINE_CHANNEL, ENABLE); /* ADC discontinuous mode */ adc_discontinuous_mode_config(ADC0, ADC_ROUTINE_CHANNEL, 3); /* enable ADC interface */ adc_enable(ADC0); delay_1ms(1); /* ADC calibration and reset calibration */ adc_calibration_enable(ADC0); } void exti_config(void) { /* connect EXTI line to GPIO pin for routine sequence */ gpio_exti_source_select(GPIO_PORT_SOURCE_GPIOA, GPIO_PIN_SOURCE_11); /* configure EXTI line for routine sequence */ exti_init(EXTI_11, EXTI_EVENT, EXTI_TRIG_RISING); exti_flag_clear(EXTI_11); } 代码讲解 printf 输出：通过串口打印调试信息。需要先调用 uart_print_init 完成重定向。
GPIO 配置：设置引脚为输出/输入模式，选择推挽/开漏输出，配置上拉/下拉。
ADC 配置：选择采样通道、采样时间、触发方式、数据对齐方式。采样时间越长精度越高。
DMA 配置：设置源地址、目标地址、传输方向、数据宽度。DMA 搬运数据不占用 CPU。
校准：ADC 使用前必须校准，消除工艺偏差。校准期间不要操作 ADC。
实验现象 串口助手打印 ADC 采样值 转动电位器时数值变化 温度传感器示例会显示芯片温度 注意事项 ADC 参考电压影响测量精度 采样时间要根据信号源阻抗选择 使用前务必校准（Calibration）

CAN — 多 CAN 通信 固件库: GD32F30x_Firmware_Library V3.0.3
芯片: GD32
源文件: GD32F30x_Firmware_Library_V3.0.3/Examples/CAN/communication_among_CANs/main.c
功能简介 本示例演示 CAN 总线通信。CAN 是汽车和工业领域最常用的现场总线，支持多主通信、错误检测和自动重传。
