&#34;); /* configure leds */ led_config(); gd_eval_led_off(LED2); gd_eval_led_off(LED3); gd_eval_led_off(LED4); gd_eval_led_off(LED5); /* initialize CAN and filter */ can_config(); /* enable can receive FIFO0 not empty interrupt */ can_interrupt_enable(CAN0, CAN_INT_RFNE0); can_interrupt_enable(CAN1, CAN_INT_RFNE0); /* initialize transmit message */ transmit_message.tx_sfid = 0x7ab; transmit_message.tx_efid = 0x00; transmit_message.tx_ft = CAN_FT_DATA; transmit_message.tx_ff = CAN_FF_STANDARD; transmit_message.tx_dlen = 8; transmit_message.tx_data[0] = 0x00; transmit_message.tx_data[1] = 0xA1; transmit_message.tx_data[2] = 0xA2; transmit_message.tx_data[3] = 0xA3; transmit_message.tx_data[4] = 0xA4; transmit_message.tx_data[5] = 0xA5; transmit_message.tx_data[6] = 0xA6; transmit_message.tx_data[7] = 0xA7; while(1){ /* test whether the Tamper key is pressed */ if(0 == gd_eval_key_state_get(KEY_TAMPER)){ transmit_message.tx_data[0] = 0x55; transmit_message.tx_data[1] = 0xAA; printf(&#34;
 can0 transmit data:&#34;); for(i = 0; i &lt; transmit_message.tx_dlen; i++){ printf(&#34; %02x&#34;, transmit_message.tx_data[i]); } /* transmit message */ transmit_mailbox = can_message_transmit(CAN0, &amp;transmit_message); /* waiting for transmit completed */ timeout = 0xFFFF; while((CAN_TRANSMIT_OK != can_transmit_states(CAN0, transmit_mailbox)) &amp;&amp; (0 != timeout)){ timeout--; } /* waiting for the Tamper key up */ while(0 == gd_eval_key_state_get(KEY_TAMPER)); } #ifdef GD32F30X_CL /* test whether the Wakeup key is pressed */ if(0 == gd_eval_key_state_get(KEY_WAKEUP)){ transmit_message.tx_data[0] = 0xAA; transmit_message.tx_data[1] = 0x55; printf(&#34;
