 can_filter.filter_number = 15; can_filter_init(&amp;can_filter); } void nvic_config(void) { #ifdef GD32F30X_CL /* configure CAN0 NVIC */ nvic_irq_enable(CAN0_RX0_IRQn,0,0); /* configure CAN1 NVIC */ nvic_irq_enable(CAN1_RX0_IRQn,1,1); #else nvic_irq_enable(USBD_LP_CAN0_RX0_IRQn,0,0); #endif /* GD32F30X_CL */ } void led_config(void) { gd_eval_led_init(LED2); gd_eval_led_init(LED3); gd_eval_led_init(LED4); gd_eval_led_init(LED5); } void can_gpio_config(void) { /* enable CAN clock */ rcu_periph_clock_enable(RCU_CAN0); #ifdef GD32F30X_CL rcu_periph_clock_enable(RCU_CAN1); #endif /* GD32F30X_CL */ rcu_periph_clock_enable(RCU_GPIOB); rcu_periph_clock_enable(RCU_GPIOD); rcu_periph_clock_enable(RCU_AF); /* configure CAN0 GPIO */ gpio_init(GPIOD,GPIO_MODE_IPU,GPIO_OSPEED_50MHZ,GPIO_PIN_0); gpio_init(GPIOD,GPIO_MODE_AF_PP,GPIO_OSPEED_50MHZ,GPIO_PIN_1); #ifdef GD32F30X_CL gpio_pin_remap_config(GPIO_CAN0_FULL_REMAP,ENABLE); #else gpio_pin_remap_config(GPIO_CAN_FULL_REMAP,ENABLE); #endif /* GD32F30X_CL */ #ifdef GD32F30X_CL /* configure CAN1 GPIO */ gpio_init(GPIOB,GPIO_MODE_IPU,GPIO_OSPEED_50MHZ,GPIO_PIN_5); gpio_init(GPIOB,GPIO_MODE_AF_PP,GPIO_OSPEED_50MHZ,GPIO_PIN_6); gpio_pin_remap_config(GPIO_CAN1_REMAP,ENABLE); #endif /* GD32F30X_CL */ } 代码讲解 printf 输出：通过串口打印调试信息。需要先调用 uart_print_init 完成重定向。
GPIO 配置：设置引脚为输出/输入模式，选择推挽/开漏输出，配置上拉/下拉。
