 External Reset occurred....&#34;); } /* allow access to BKP domain */ rcu_periph_clock_enable(RCU_PMU); pmu_backup_write_enable(); printf(&#34;
 No need to configure RTC....&#34;); /* wait for RTC registers synchronization */ rtc_register_sync_wait(); /* enable the RTC second */ rtc_interrupt_enable(RTC_INT_SECOND); /* wait until last write operation on RTC registers has finished */ rtc_lwoff_wait(); } #ifdef RTCCLOCKOUTPUT_ENABLE /* enable PMU and BKPI clocks */ rcu_periph_clock_enable(RCU_BKPI); rcu_periph_clock_enable(RCU_PMU); /* allow access to BKP domain */ pmu_backup_write_enable(); /* disable the tamper pin */ bkp_tamper_detection_disable(); /* enable RTC clock output on tamper Pin */ bkp_rtc_calibration_output_enable(); #endif /* clear reset flags */ rcu_all_reset_flag_clear(); /* display time in infinite loop */ time_show(); while (1){ } } 代码讲解 printf 输出：通过串口打印调试信息。需要先调用 uart_print_init 完成重定向。
